import {services} from '../../server/qa-armgarage-image/catalog.mjs';
/** Synthetic domain module used to validate trusted tests, never written into the user project. */
export function armgarageDomain(mutation='none'){return `
export interface Service {id:string;category:string;name:string;price:number;minutes:number}
export const SERVICES:Service[]=${JSON.stringify(services)};
const mutation:string=${JSON.stringify(mutation)},factors:Record<string,number>={car:1,crossover:1.15,suv:1.3};
export function filterServices(query:string,category='all',sort='price-asc',catalogue=SERVICES){if(!['all','diagnostics','maintenance','brakes-suspension','electrical'].includes(category)||!['price-asc','price-desc'].includes(sort))throw Error('Unknown filter');return catalogue.filter(s=>(category==='all'||s.category===category)&&s.name.toLowerCase().includes(query.trim().toLowerCase())).sort((a,b)=>mutation==='wrong-sort'?String(a.price).localeCompare(String(b.price)):sort==='price-desc'?b.price-a.price:a.price-b.price);}
export function calculateEstimate(ids:string[],vehicle='car',urgent=false,catalogue=SERVICES){if(!Object.hasOwn(factors,vehicle))throw Error('Unknown vehicle');const selected=[...new Set(ids)].map(id=>{const s=catalogue.find(s=>s.id===id);if(!s||!Number.isFinite(s.price)||s.price<0)throw Error('Invalid service');return s;});const subtotal=selected.reduce((n,s)=>n+s.price,0),value=subtotal*factors[vehicle]*(urgent?1.2:1);return {subtotal,total:mutation==='floor-rounding'?Math.floor(value):Math.round(value),minutes:selected.reduce((n,s)=>n+s.minutes,0)};}
export function normalizePhone(value:unknown){if(typeof value!=='string')return null;const clean=mutation==='accept-letters'?value.replace(/[^+0-9]/g,''):value.replace(/[\\s()-]/g,'');if(/^0\\d{8}$/.test(clean))return '+374'+clean.slice(1);return /^\\+374\\d{8}$/.test(clean)?clean:null;}
export function validateBooking(data:any,todayISO:string){const e:Record<string,string>={};if(!String(data.name??'').trim())e.name='Name';if(!normalizePhone(data.phone))e.phone='Phone';if(!String(data.car??'').trim())e.car='Car';if(!Array.isArray(data.serviceIds)||!data.serviceIds.length||data.serviceIds.some((id:string)=>!SERVICES.some(s=>s.id===id)))e.services='Services';const date=new Date(data.date+'T12:00:00Z');if(!/^\\d{4}-\\d{2}-\\d{2}$/.test(data.date)||!Number.isFinite(date.getTime())||date.toISOString().slice(0,10)!==data.date||(mutation!=='past-date-allowed'&&data.date<todayISO))e.date='Date';if(!['09:00','11:00','14:00','16:00'].includes(data.time))e.time='Time';if(data.consent!==true)e.consent='Consent';if(String(data.comment??'').length>500)e.comment='Comment';return e;}
`;}
